import{_ as s,a0 as r,w as l,s as m,ao as i,I as n,a1 as o,A as a,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何使用 pv 命令监控 linux 命令的执行进度 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 pv 命令监控 linux 命令的执行进度 | LCTT (201512) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 pv 命令监控 linux 命令的执行进度 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 pv 命令监控 linux 命令的执行进度 | LCTT (201512) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201512/20151109 How to Monitor the Progress of a Linux Command Line Operation Using PV Command","title":"如何使用 pv 命令监控 linux 命令的执行进度","tag":"201512","desc":""},"relativePath":"201512/20151109 How to Monitor the Progress of a Linux Command Line Operation Using PV Command.md","filePath":"[post].md"}'),d={name:"201512/20151109 How to Monitor the Progress of a Linux Command Line Operation Using PV Command.md"};function u(f,e,v,g,h,x){const p=r("Link");return l(),m("div",null,[e[18]||(e[18]=i('<h1 id="如何使用-pv-命令监控-linux-命令的执行进度" tabindex="-1">如何使用 pv 命令监控 linux 命令的执行进度 <a class="header-anchor" href="#如何使用-pv-命令监控-linux-命令的执行进度" aria-label="Permalink to “如何使用 pv 命令监控 linux 命令的执行进度”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2015/11/pv-featured-1.jpg" alt=""></p><p>如果你是一个 linux 系统管理员，那么毫无疑问你必须花费大量的工作时间在命令行上：安装和卸载软件，监视系统状态，复制、移动、删除文件，查错，等等。很多时候都是你输入一个命令，然后等待很长时间直到执行完成。也有的时候你执行的命令挂起了，而你只能猜测命令执行的实际情况。</p><p>通常 linux 命令不提供和进度相关的信息，而这些信息特别重要，尤其当你只有有限的时间时。然而这并不意味着你是无助的——现在有一个命令，pv，它会显示当前在命令行执行的命令的进度信息。在本文我们会讨论它并用几个简单的例子说明其特性。</p><h3 id="pv-命令" tabindex="-1">PV 命令 <a class="header-anchor" href="#pv-命令" aria-label="Permalink to “PV 命令”">​</a></h3>',5)),n("p",null,[o(p,{href:"http://linux.die.net/man/1/pv"},{default:a(()=>[...e[0]||(e[0]=[t("PV",-1)])]),_:1}),e[1]||(e[1]=t(" 由Andrew Wood 开发，是 Pipe Viewer 的简称，意思是通过管道显示数据处理进度的信息。这些信息包括已经耗费的时间，完成的百分比（通过进度条显示），当前的速度，全部传输的数据，以及估计剩余的时间。",-1))]),e[19]||(e[19]=i(`<blockquote><p>&quot;要使用 PV，需要配合合适的选项，把它放置在两个进程之间的管道。命令的标准输入将会通过标准输出传进来的，而进度会被输出到标准错误输出。”</p></blockquote><p>上述解释来自该命令的帮助页。</p><h3 id="下载和安装" tabindex="-1">下载和安装 <a class="header-anchor" href="#下载和安装" aria-label="Permalink to “下载和安装”">​</a></h3><p>Debian 系的操作系统，如 Ubuntu，可以简单的使用下面的命令安装 PV：</p><pre><code>sudo apt-get install pv
</code></pre><p>如果你使用了其他发行版本，你可以使用各自的包管理软件在你的系统上安装 PV。一旦 PV 安装好了你就可以在各种场合使用它（详见下文）。需要注意的是下面所有例子都使用的是 pv 1.2.0。</p><h3 id="特性和用法" tabindex="-1">特性和用法 <a class="header-anchor" href="#特性和用法" aria-label="Permalink to “特性和用法”">​</a></h3><p>我们（在 linux 上使用命令行的用户）的大多数使用场景都会用到的命令是从一个 USB 驱动器拷贝电影文件到你的电脑。如果你使用 cp 来完成上面的任务，你会什么情况都不清楚，直到整个复制过程结束或者出错。</p><p>然而pv 命令在这种情景下很有帮助。比如：</p><pre><code>pv /media/himanshu/1AC2-A8E3/fNf.mkv &gt; ./Desktop/fnf.mkv
</code></pre><p>输出如下：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/pv-copy.png" alt="pv-copy"></p><p>所以，如你所见，这个命令显示了很多和操作有关的有用信息，包括已经传输了的数据量，花费的时间，传输速率，进度条，进度的百分比，以及剩余的时间。</p><p><code>pv</code> 命令提供了多种显示选项开关。比如，你可以使用<code>-p</code> 来显示百分比，<code>-t</code> 来显示时间，<code>-r</code> 表示传输速率，<code>-e</code> 代表eta（LCTT 译注：估计剩余的时间）。好事是你不必记住某一个选项，因为默认这几个选项都是启用的。但是，如果你只要其中某一个信息，那么可以通过控制这几个选项来完成任务。</p><p>这里还有一个<code>-n</code> 选项来允许 pv 命令显示整数百分比，在标准错误输出上每行显示一个数字，用来替代通常的可视进度条。下面是一个例子：</p><pre><code>pv -n /media/himanshu/1AC2-A8E3/fNf.mkv &gt; ./Desktop/fnf.mkv
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/pv-numeric.png" alt="pv-numeric"></p>`,17)),n("p",null,[e[3]||(e[3]=t("这个特殊的选项非常合适某些情境下的需求，如你想把用管道把输出传给",-1)),o(p,{href:"http://linux.die.net/man/1/dialog"},{default:a(()=>[...e[2]||(e[2]=[t("dialog",-1)])]),_:1}),e[4]||(e[4]=t(" 命令。",-1))]),e[20]||(e[20]=i(`<p>接下来还有一个命令行选项，<code>-L</code> 可以让你修改 pv 命令的传输速率。举个例子，使用 -L 选项来限制传输速率为2MB/s。</p><pre><code>pv -L 2m /media/himanshu/1AC2-A8E3/fNf.mkv &gt; ./Desktop/fnf.mkv
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/pv-ratelimit.png" alt="pv-ratelimit"></p><p>如上图所见，数据传输速度按照我们的要求被限制了。</p><p>另一个pv 可以帮上忙的情景是压缩文件。这里有一个例子可以向你解释如何与压缩软件Gzip 一起工作。</p><pre><code>pv /media/himanshu/1AC2-A8E3/fnf.mkv | gzip &gt; ./Desktop/fnf.log.gz
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/pv-gzip.png" alt="pv-gzip"></p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>如上所述，pv 是一个非常有用的小工具，它可以在命令没有按照预期执行的情况下帮你节省你宝贵的时间。而且这些显示的信息还可以用在 shell 脚本里。我强烈的推荐你使用这个命令，它值得你一试。</p><hr>`,10)),n("p",null,[e[6]||(e[6]=t("via: ",-1)),o(p,{href:"https://www.maketecheasier.com/monitor-progress-linux-command-line-operation/"},{default:a(()=>[...e[5]||(e[5]=[t("https://www.maketecheasier.com/monitor-progress-linux-command-line-operation/",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=t("作者：",-1)),o(p,{href:"https://www.maketecheasier.com/author/himanshu/"},{default:a(()=>[...e[7]||(e[7]=[t("Himanshu Arora",-1)])]),_:1}),e[11]||(e[11]=t(" 译者：",-1)),o(p,{href:"https://github.com/oska874"},{default:a(()=>[...e[8]||(e[8]=[t("ezio",-1)])]),_:1}),e[12]||(e[12]=t(" 校对：",-1)),o(p,{href:"https://github.com/wxy"},{default:a(()=>[...e[9]||(e[9]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[15]||(e[15]=t("本文由 ",-1)),o(p,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[13]||(e[13]=[t("LCTT",-1)])]),_:1}),e[16]||(e[16]=t(" 原创编译，",-1)),o(p,{href:"https://linux.cn/"},{default:a(()=>[...e[14]||(e[14]=[t("Linux中国",-1)])]),_:1}),e[17]||(e[17]=t(" 荣誉推出",-1))])])}const k=s(d,[["render",u]]);export{C as __pageData,k as default};
